package com.siestech.booksharing.Practical;
import android.content.Intent; import android.os.Bundle; import android.widget.TextView; import android.widget.Toast; import androidx.appcompat.app.AppCompatActivity; import com.siestech.booksharing.Model.Book; import com.siestech.booksharing.R; import com.siestech.booksharing.Utils.LocalBookStore;
public class ShareTextActivity extends AppCompatActivity{private String text="";@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_share_text);TextView out=findViewById(R.id.sharedText);Intent i=getIntent();if(Intent.ACTION_SEND.equals(i.getAction())&&i.getType()!=null&&i.getType().startsWith("text/"))text=i.getStringExtra(Intent.EXTRA_TEXT);if(text==null)text="";out.setText(text.isEmpty()?"No text was shared.":text);findViewById(R.id.saveSharedBtn).setOnClickListener(v->{String first=text.isEmpty()?"Shared Book":text.split("\\n")[0];Book b1=new Book("shared_"+System.currentTimeMillis(),first,"Unknown","Shared","Imported from another application.","local","Shared user","","Good","book1",true,System.currentTimeMillis());LocalBookStore.save(this,b1);Toast.makeText(this,"Saved to local BorrowBox books",Toast.LENGTH_SHORT).show();});}}
